  const w = m[3];
  let x;
  if (!w) work = '';
  else if ((x = /^(\w+) sets? of papers to mark, (\w+) ready to hand back\.$/i.exec(w))) work = esSets(esN(x[1])) + ' por corregir y ' + esW(esN(x[2]), false, true) + (esN(x[2]) === 1 ? ' listo' : ' listos') + ' para devolver.';
  else if ((x = /^(\w+) sets? of papers to mark\.$/i.exec(w))) work = esSets(esN(x[1])) + ' por corregir.';
  else if ((x = /^(\w+) sets? of papers ready to hand back\.$/i.exec(w))) work = esSets(esN(x[1])) + (esN(x[1]) === 1 ? ' listo' : ' listos') + ' para devolver.';
  else if (/^nothing waiting to be marked\.$/i.test(w)) work = 'nada por corregir.';
